// Ventana de busqueda en Loki: desde la ultima ejecucion hasta ahora (sin huecos ni duplicados)
const estado = $getWorkflowStaticData('global');
const fin = Date.now();
const inicio = estado.ultimoFin && fin - estado.ultimoFin < 3600000 ? estado.ultimoFin : fin - 60000;
estado.ultimoFin = fin;
return [{ json: { start: (BigInt(inicio) * 1000000n).toString(), end: (BigInt(fin) * 1000000n).toString() } }];

// Convierte cada linea de Loki en un mensaje con el formato estandar del proyecto
const fmt = ns => new Date(Number(BigInt(ns) / 1000000n))
  .toLocaleString('sv-SE', { timeZone: 'America/Costa_Rica' });
const out = [];
for (const s of $input.first().json.data?.result ?? []) {
  for (const [ts, linea] of s.values) {
    const esComando = s.stream.job === 'auth';
    const usuario = (linea.match(/sudo:\s+(\S+)\s*:/) || [])[1] || 'desconocido';
    const comando = (linea.match(/COMMAND=(.*)$/) || [])[1] || '';
    const src = (linea.match(/SRC=(\S+)/) || [])[1] || '';
    const detalle = esComando
      ? `Comando: ${comando}\nUsuario: ${usuario}`
      : `Trafico permitido al puerto 5432 desde ${src}\nLinea ufw.log: ${linea.slice(0, 300)}`;
    out.push({ json: {
      linea: linea.slice(0, 1000),
      mensaje: [
        'ALERTA CRÍTICA - NutriAnimales S.A. | Lead University BCD 9220',
        `Tipo: ${esComando ? 'Regla UFW modificada' : 'Puerto de BD abierto en UFW'} (H1)`,
        `Fecha: ${fmt(ts)}`,
        detalle,
        `Fuente: ${s.stream.job === 'auth' ? '/var/log/auth.log' : '/var/log/ufw.log'} via Loki`,
        'Severidad: CRÍTICA',
        'Acción: Verificar si el cambio fue autorizado. Revisar sudo ufw status numbered y revertir con sudo ufw delete <n>.'
      ].join('\n')
    }});
  }
}
return out;

